precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(set = 2, binding = 0) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
layout(set = 1, binding = 0) uniform OceanParams {
  vec4 waveControl;
  vec4 waveDetail;
  vec4 shallowColor;
  vec4 deepColor;
  vec4 colorParams;
  vec4 surfaceParams;
  vec4 waveAdvanced;
  vec4 sssColor;
  vec4 foamColor;
  vec4 envParams;
  vec4 fogColor;
  vec4 causticsParams;
};
vec2 hash22(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}
void computeSpectralWaves(vec2 pos, float time,
                          out vec3 displacement, out vec3 normalOffset) {
  float windAng  = waveControl.x;
  float size     = max(waveControl.y, 0.01);
  float height   = waveControl.z;
  float speed    = waveControl.w;
  float choppy   = waveDetail.x;
  float octaves  = max(waveAdvanced.x, 1.0);
  float randomness = waveAdvanced.y;
  float freqRatio = max(surfaceParams.w, 1.1);
  displacement = vec3(0.0);
  normalOffset = vec3(0.0);
  float baseFreq = 0.2 / size;
  float goldenAngle = 2.39996323;
  float freq = baseFreq;
  float amp  = height;
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float activeMask = step(fi + 0.5, octaves);
    float activeAmp = amp * activeMask;
    if (activeAmp < 0.0001 && fi > 0.0) { freq *= 1.6; amp *= 0.5; continue; }
    float baseAngle = windAng + fi * goldenAngle;
    float angleJitter = (hash22(vec2(fi * 7.31, fi * 3.17)).x) * randomness * 1.5;
    float angle = baseAngle + angleJitter;
    vec2 dir = vec2(cos(angle), sin(angle));
    float windAlignment = dot(dir, vec2(cos(windAng), sin(windAng)));
    float alignedAmp = activeAmp * (0.7 + 0.3 * max(windAlignment, 0.0));
    float omega = sqrt(9.8 * max(freq, 0.001)) * speed;
    float Q = choppy / max(freq * alignedAmp * 8.0, 0.001);
    Q = min(Q, 0.95);
    float phase = freq * dot(dir, pos) - omega * time;
    float s = sin(phase);
    float c = cos(phase);
    displacement.xz += Q * alignedAmp * dir * c;
    displacement.y  += alignedAmp * s;
    normalOffset.x += dir.x * freq * alignedAmp * c;
    normalOffset.y += Q * freq * alignedAmp * s;
    normalOffset.z += dir.y * freq * alignedAmp * c;
    freq *= freqRatio;
    amp  *= 0.5;
  }
}
layout(location = 0) in vec3 a_position;
layout(location = 1) in vec3 a_normal;
layout(location = 2) in vec2 a_texCoord;
layout(location = 0) out vec3 v_worldPos;
layout(location = 1) out vec2 v_uv;
layout(location = 2) out float v_waveHeight;
layout(location = 3) out vec3 v_waveNormal;
layout(location = 4) out vec3 v_viewDir;
layout(location = 5) out float v_waveSteepness;
vec4 vert() {
  vec4 worldPos = cc_matWorld * vec4(a_position, 1.0);
  float time = cc_time.x;
  vec2 origXZ = worldPos.xz;
  vec3 displacement, normOff;
  computeSpectralWaves(origXZ, time, displacement, normOff);
  worldPos.xyz += displacement;
  vec3 waveNorm = normalize(vec3(-normOff.x, 1.0 - normOff.y, -normOff.z));
  v_worldPos = worldPos.xyz;
  v_uv = a_texCoord;
  v_waveHeight = displacement.y;
  v_waveNormal = waveNorm;
  v_waveSteepness = 1.0 - waveNorm.y;
  v_viewDir = normalize(cc_cameraPos.xyz - worldPos.xyz);
  return cc_matProj * cc_matView * worldPos;
}
void main() { gl_Position = vert(); }

