  float roughness = max(1.0 - smoothness, 0.01);
  float a = roughness * roughness;
  float a2 = a * a;
  float k = (a + 1.0) * (a + 1.0) / 8.0;
  vec3 H = normalize(V + L);
  float NoH = max(dot(N, H), 0.0);
  float NoV = max(dot(N, V), 0.001);
  float NoL = max(dot(N, L), 0.0);
  float VoH = max(dot(V, H), 0.0);
  float D = D_GGX(NoH, a2);
  float G = G_SmithGGX(NoV, NoL, k);
  float F = 0.02 + 0.98 * pow(1.0 - VoH, 5.0);
  float spec = (D * G * F) / max(4.0 * NoV * NoL, 0.001);
  return cc_mainLitColor.xyz * cc_mainLitColor.w * spec * intensity;
}
float oceanSparkle(vec2 worldXZ, vec3 N, vec3 V, vec3 L, float time) {
  float smoothness = surfaceParams.x;
  float roughness = 1.0 - smoothness;
  if (smoothness < 0.3) return 0.0;
  float uvScale = mix(25.0, 12.0, smoothness);
  vec2 uv = worldXZ * uvScale + vec2(time * 0.4, time * 0.23);
  float n = oceanNoise(uv);
  float exponent = mix(6.0, 14.0, smoothness);
  float sparkle = pow(max(n, 0.0), exponent) * 40.0;
  vec2 uv2 = worldXZ * uvScale * 2.1 + vec2(-time * 0.3, time * 0.5);
  float n2 = oceanNoise(uv2);
  float sparkle2 = pow(max(n2, 0.0), exponent * 1.5) * 20.0;
  sparkle += sparkle2 * 0.3;
  float NoL = max(dot(N, L), 0.0);
  sparkle *= NoL * smoothness;
  return sparkle;
}
float oceanFoam(vec2 worldXZ, float waveHeight, float waveSteepness, float time) {
  float amount = waveDetail.w;
  if (amount < 0.001) return 0.0;
  float size = max(waveControl.y, 0.01);
  float foamSize = max(envParams.w, 0.5);
  vec2 uv = worldXZ / size;
  float heightFoam = smoothstep(0.1, 0.6, waveHeight / max(waveControl.z, 0.01));
  float steepness = clamp(waveSteepness * 2.0, 0.0, 1.0);
  float whitecapFoam = smoothstep(0.3, 0.8, steepness);
  float foamFactor = max(heightFoam, whitecapFoam * 0.6);
  float noise1 = oceanNoise(uv * foamSize + vec2(time * 0.2, time * 0.15));
  float noise2 = oceanNoise(uv * foamSize * 2.2 + vec2(-time * 0.15, time * 0.25));
  foamFactor *= (0.5 + 0.3 * noise1 + 0.2 * noise2);
  foamFactor *= smoothstep(0.1, 0.4, foamFactor);
  return clamp(foamFactor * amount, 0.0, 1.0);
}
float oceanVoronoi(vec2 uv) {
  vec2 i = floor(uv);
  vec2 f = fract(uv);
  float minDist = 1.0;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 neighbor = vec2(float(x), float(y));
      vec2 point = hash22(i + neighbor);
      point = 0.5 + 0.5 * sin(cc_time.x * causticsParams.z * 0.5 + 6.2831 * point);
      vec2 diff = neighbor + point - f;
      float dist = length(diff);
      minDist = min(minDist, dist);
    }
  }
  return minDist;
}
float oceanCaustics(vec2 worldXZ) {
  float intensity = causticsParams.x;
  float scale = causticsParams.y;
  float speed = causticsParams.z;
  if (intensity < 0.001) return 0.0;
  float time = cc_time.x;
  vec2 uv1 = worldXZ * scale * 0.1 + vec2(time * speed * 0.1, time * speed * 0.07);
  vec2 uv2 = worldXZ * scale * 0.13 + vec2(-time * speed * 0.08, time * speed * 0.12);
  float v1 = oceanVoronoi(uv1);
  float v2 = oceanVoronoi(uv2);
  float caustic1 = pow(1.0 - smoothstep(0.0, 0.3, v1), 2.0);
  float caustic2 = pow(1.0 - smoothstep(0.0, 0.35, v2), 2.0);
  float caustics = caustic1 * 0.7 + caustic2 * 0.3;
  return caustics * intensity;
}
varying vec3 v_worldPos;
